	'forms_email' => 'E-Mail-Adresse',
	'forms_mail_notice' => 'Hierdurch öffnet sich Ihre E-Mail-App mit bereits eingetragener Adresse. Senden Sie die Nachricht ab, um Termin-Benachrichtigungen zu erhalten; Sie stehen erst auf der Liste, wenn wir antworten.',
	'forms_mail_subject' => 'Termin-Benachrichtigungen: Noki Surveyors',
