	'pb_1' => 'Risse',
	'pb_2' => 'Feuchtigkeit',
	'pb_3' => 'das Dach',
	'ppl_h' => 'Wer ins Haus kommt',
	'ppl_l' => 'Team',
	'ppl_p' => 'Ines Kovač gründete Noki Surveyors im Jahr 2011 in Elsmere Quay. Fünf Personen arbeiten von 3 Ropewalk Yard aus, mit einem Lieferwagen, einer Leiter und einer Teleskopkamera. Das Untersuchungsgebiet liegt im Umkreis von 40 km um Elsmere Quay, und etwa zwölf Gebäude werden in der Woche begutachtet.',
	'pr1_a' => 'Wohnung oder kleines Haus',
	'pr1_b' => 'Bis zu 90 m², vollständiger Zustandsbericht',
	'pr1_c' => 'etwa 90 Min.',
