	'pr3_d' => 'EUR 820',
	'pr4_a' => 'Kleines Gewerbegebäude',
	'pr4_b' => 'Laden, Büro oder Werkstatt bis zu 400 m², einschließlich einer Wohnung darüber',
	'pr4_c' => 'etwa 4 Std.',
	'pr4_d' => 'EUR 1,150',
	'pr5_a' => 'Einzelschadenprüfung',
	'pr5_b' => 'Ein Riss, Feuchtigkeitsfleck oder Leck, kurzes Schreiben',
